                                    for c in range(c0, c1 + 1))):
                            continue
                        if not all(grid[r][c0] == color and grid[r][c1] == color
                                   for r in range(r0, r1 + 1)):
                            continue
                        # Only fill an outline whose inside is otherwise empty
                        # (or already contains the special inset color 2).
