                                    for c in range(c0 + 1, c1)]
                        if all(v in (bg, 2) for v in interior):
                            fill = 7
                            for r in range(r0 + 1, r1):
                                for c in range(c0 + 1, c1):
                                    if grid[r][c] == bg:
                                        out[r][c] = fill
    return out
